const body = $input.first().json.body;

const required = ['talk_title', 'abstract', 'conference_name'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

if (body.abstract.trim().length < 80) {
  return [{ json: { valid: false, error: 'Abstract too short — minimum 80 characters' } }];
}

const formats = ['keynote', 'full_talk', 'lightning_talk', 'workshop', 'panel', 'tutorial'];
const format = formats.includes(body.format) ? body.format : 'full_talk';

return [{
  json: {
    valid: true,
    talkTitle: body.talk_title.trim(),
    abstract: body.abstract.trim().slice(0, 3000),
    outlineOrNotes: (body.outline_or_notes || '').trim().slice(0, 2000),
    conferenceName: body.conference_name.trim(),
    conferenceUrl: body.conference_url || '',
    audienceLevel: body.audience_level || 'intermediate',
    format,
    speakerBio: (body.speaker_bio || '').slice(0, 800),
    speakerEmail: body.speaker_email || null,
    submissionDeadline: body.submission_deadline || '',
    previousTalks: body.previous_talks || '',
    specificConcerns: (body.specific_concerns || '').slice(0, 500),
    requestedAt: new Date().toISOString()
  }
}];

const confSearch = $('Research Conference').first().json;
const input = $('Validate Input').first().json;

const confContext = (confSearch.results || [])
  .map(r => `${r.title}: ${(r.content || r.snippet || '').slice(0, 300)}`)
  .join('\n\n');

return [{ json: { input, confContext: confContext || 'No conference context found' } }];

values.content:
Review this conference talk submission and provide coaching.

Submission details:
- Title: {{ $json.input.talkTitle }}
- Conference: {{ $json.input.conferenceName }}
- Format: {{ $json.input.format }}
- Audience level: {{ $json.input.audienceLevel }}
- Deadline: {{ $json.input.submissionDeadline || 'not specified' }}
- Specific concerns from speaker: {{ $json.input.specificConcerns || 'none' }}

Abstract:
{{ $json.input.abstract }}

Outline/notes (if provided):
{{ $json.input.outlineOrNotes || 'Not provided' }}

Speaker bio (if provided):
{{ $json.input.speakerBio || 'Not provided' }}

Previous talks:
{{ $json.input.previousTalks || 'Not provided' }}

Conference context from web research:
{{ $json.confContext }}

Provide your coaching as this JSON:
{
  "overall_score": 7,
  "verdict": "one of: strong_submit | submit_with_tweaks | significant_revision_needed | rethink_angle",
  "one_line_summary": "your honest one-sentence read on where this submission stands right now",
  "strengths": ["2-4 genuine strengths — be specific, not generic"],
  "critical_issues": [
    {
      "issue": "what the problem is",
      "why_it_matters": "how it hurts the submission",
      "fix": "exactly what to do"
    }
  ],
  "title_feedback": {
    "assessment": "honest assessment of the current title",
    "alternative_titles": ["3 alternative title options — ranging from safe to bold"]
  },
  "abstract_rewrite": "a full rewritten version of the abstract incorporating your feedback — keep it roughly the same length as the original but make it sharper. This should be copy-paste ready.",
  "structure_suggestions": [
    "if an outline was provided or can be inferred: 3-5 structural suggestions to make the talk flow better or land harder"
  ],
  "bio_feedback": "feedback on the speaker bio if provided, or what to include if not. One short paragraph.",
  "differentiation": "what would make this talk stand out from other submissions on similar topics — be specific about what angle or hook is most distinctive",
  "committee_perspective": "2-3 sentences written as if you're a committee member reading this — what would you be thinking, what questions would you have, what would make you vote yes or hesitate"
}

