const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let feedback;
try {
  feedback = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const input = $('Validate Input').first().json;
feedback._speakerEmail = input.speakerEmail;
feedback._conferenceName = input.conferenceName;
feedback._talkTitle = input.talkTitle;
feedback._deadline = input.submissionDeadline;
return [{ json: feedback }];
